export const SYMPY_BUILDER_PYTHON_SOURCE = "\"\"\"\nIntersect — Safe Allowlisted SymPy Expression Builder and Exact Intersection Engine (Phase V4)\n\nSecurity & Architecture Guarantees:\n1. Zero eval(), exec(), or arbitrary code generation from user input.\n2. Accepts ONLY declarative JSON construction steps generated by the V2 TypeScript pipeline.\n3. Every operation, symbol, and constant is verified against a strict finite allowlist.\n4. All symbols are instantiated with real=True to enforce real-valued geometry.\n5. Real root semantics: Odd roots of negative bases evaluate to real numbers via sp.real_root.\n6. Domain obligations and equations are preserved separately from automatic simplifications.\n7. Pure JSON-serializable outputs; PyProxy objects must be destroyed in JS callers.\n8. Bounded Portfolio of General Symbolic Strategies:\n   - Safe preprocessing, trivial contradiction & degeneracy detection\n   - Linear systems (affine planes intersection, lines, coincident 2D overlap)\n   - Plane-conic and structured quadric strategies (plane-sphere, cylinder-plane)\n   - Quadric-quadric reduction (elimination of shared quadratic parts to plane-conic)\n   - Coordinate parameterization & substitution (x=t, y=t, z=t with domain and box clipping)\n   - Rigorous candidate certification, deterministic ranking, and transformation recording\n\"\"\"\n\nimport json\nimport math\nimport time\nimport sympy as sp\n\n# Supported constant mapping\nALLOWED_CONSTANTS = {\n    'pi': sp.pi,\n    'E': sp.E,\n}\n\n# Allowlisted symbol names for Cartesian coordinates and parameter\nx, y, z = sp.symbols('x y z', real=True)\nt = sp.Symbol('t', real=True)\n\nALLOWED_SYMBOLS = {'x': x, 'y': y, 'z': z, 't': t}\n\nDEFAULT_BOUNDS = {\n    'minX': -1000, 'maxX': 1000,\n    'minY': -1000, 'maxY': 1000,\n    'minZ': -1000, 'maxZ': 1000\n}\n\n\ndef normalize_bounds(b):\n    if isinstance(b, dict):\n        return [\n            b.get('xMin', b.get('minX', -1000)),\n            b.get('xMax', b.get('maxX', 1000)),\n            b.get('yMin', b.get('minY', -1000)),\n            b.get('yMax', b.get('maxY', 1000)),\n            b.get('zMin', b.get('minZ', -1000)),\n            b.get('zMax', b.get('maxZ', 1000)),\n        ]\n    return list(b)\n\n\ndef build_step(step):\n    \"\"\"\n    Recursively constructs a SymPy expression tree from a validated SymPyConstructionStep.\n    Raises ValueError on any unsupported operator or invalid structure.\n    \"\"\"\n    if not isinstance(step, dict):\n        raise ValueError(f\"Invalid construction step: expected dict, got {type(step).__name__}\")\n\n    op = step.get('op')\n    if not op or not isinstance(op, str):\n        raise ValueError(\"Construction step missing 'op' property\")\n\n    if op == 'Integer':\n        val_str = str(step.get('value', '0'))\n        return sp.Integer(int(val_str))\n\n    elif op == 'Rational':\n        num_str = str(step.get('num', '0'))\n        den_str = str(step.get('den', '1'))\n        den = int(den_str)\n        if den == 0:\n            raise ValueError(\"Zero denominator in Rational construction step\")\n        return sp.Rational(int(num_str), den)\n\n    elif op == 'Symbol':\n        name = step.get('name')\n        if not isinstance(name, str) or name not in ALLOWED_SYMBOLS:\n            raise ValueError(f\"Disallowed or unknown symbol: {name}\")\n        return ALLOWED_SYMBOLS[name]\n\n    elif op == 'Constant':\n        name = step.get('name')\n        if not isinstance(name, str) or name not in ALLOWED_CONSTANTS:\n            raise ValueError(f\"Disallowed or unknown constant: {name}\")\n        return ALLOWED_CONSTANTS[name]\n\n    # Operator node handling\n    args_raw = step.get('args')\n    if not isinstance(args_raw, list):\n        raise ValueError(f\"Operator step '{op}' must contain 'args' list\")\n\n    args = [build_step(a) for a in args_raw]\n\n    if op == 'Add':\n        return sp.Add(*args)\n\n    elif op == 'Mul':\n        return sp.Mul(*args)\n\n    elif op == 'Pow':\n        if len(args) != 2:\n            raise ValueError(f\"Pow operator requires exactly 2 arguments, got {len(args)}\")\n        base, exp = args[0], args[1]\n        # Real root compatibility:\n        # SymPy's default sp.Pow(-8, 1/3) evaluates to complex 1 + sqrt(3)*I on the principal branch.\n        # In real-valued geometry, an odd root of a real number is uniquely real.\n        if isinstance(exp, sp.Rational) and exp.q % 2 != 0:\n            return sp.real_root(base, exp.q) ** exp.p\n        return sp.Pow(base, exp)\n\n    elif op == 'Sqrt':\n        if len(args) != 1:\n            raise ValueError(f\"Sqrt operator requires exactly 1 argument, got {len(args)}\")\n        return sp.sqrt(args[0])\n\n    elif op == 'Root':\n        if len(args) != 2:\n            raise ValueError(f\"Root operator requires exactly 2 arguments (radicand, index), got {len(args)}\")\n        radicand, index = args[0], args[1]\n        if isinstance(index, sp.Integer) and index % 2 != 0:\n            return sp.real_root(radicand, int(index))\n        elif isinstance(index, sp.Rational) and index.p % 2 != 0:\n            inv = sp.Pow(index, -1)\n            if isinstance(inv, sp.Rational) and inv.q % 2 != 0:\n                return sp.real_root(radicand, inv.q) ** inv.p\n        return sp.Pow(radicand, sp.Pow(index, -1))\n\n    elif op == 'Abs':\n        if len(args) != 1:\n            raise ValueError(\"Abs operator requires exactly 1 argument\")\n        return sp.Abs(args[0])\n\n    elif op == 'Sin':\n        return sp.sin(args[0])\n    elif op == 'Cos':\n        return sp.cos(args[0])\n    elif op == 'Tan':\n        return sp.tan(args[0])\n    elif op == 'Sec':\n        return sp.sec(args[0])\n    elif op == 'Csc':\n        return sp.csc(args[0])\n    elif op == 'Cot':\n        return sp.cot(args[0])\n\n    elif op == 'ArcSin':\n        return sp.asin(args[0])\n    elif op == 'ArcCos':\n        return sp.acos(args[0])\n    elif op == 'ArcTan':\n        return sp.atan(args[0])\n\n    elif op == 'Sinh':\n        return sp.sinh(args[0])\n    elif op == 'Cosh':\n        return sp.cosh(args[0])\n    elif op == 'Tanh':\n        return sp.tanh(args[0])\n\n    elif op == 'Exp':\n        return sp.exp(args[0])\n    elif op == 'Log':\n        return sp.log(args[0])\n\n    elif op == 'Eq':\n        if len(args) != 2:\n            raise ValueError(\"Eq operator requires exactly 2 arguments\")\n        return sp.Eq(args[0], args[1])\n\n    else:\n        raise ValueError(f\"Unsupported construction operator: '{op}'\")\n\n\ndef build_surface(plan):\n    \"\"\"\n    Constructs SymPy objects for a single surface plan, producing serializable summary data.\n    \"\"\"\n    if not isinstance(plan, dict):\n        raise ValueError(\"Surface plan must be a dict\")\n\n    target = plan.get('target')\n    if target != 'sympy':\n        raise ValueError(f\"Unsupported plan target: {target}\")\n\n    eq_step = plan.get('equation')\n    if not eq_step or eq_step.get('op') != 'Eq':\n        raise ValueError(\"Invalid equation step: expected Eq relation\")\n\n    lhs_expr = build_step(eq_step['args'][0])\n    rhs_expr = build_step(eq_step['args'][1])\n    equation = sp.Eq(lhs_expr, rhs_expr)\n\n    residual = lhs_expr - rhs_expr\n    simplified_residual = sp.simplify(residual)\n\n    free_syms = sorted([s.name for s in residual.free_symbols if isinstance(s, sp.Symbol)])\n    symbols_sp = [ALLOWED_SYMBOLS[name] for name in free_syms if name in ALLOWED_SYMBOLS]\n\n    raw_conditions = plan.get('domainConditions', [])\n    domain_conditions = []\n    for cond in raw_conditions:\n        c_step = cond.get('condition')\n        c_expr = build_step(c_step) if c_step else None\n        kind = cond.get('kind', 'unknown')\n        c_str = str(c_expr) if c_expr is not None else ''\n\n        domain_conditions.append({\n            'id': cond.get('id', ''),\n            'kind': kind,\n            'conditionStr': c_str,\n            'description': cond.get('description', ''),\n        })\n\n    is_poly = False\n    degree = None\n    if symbols_sp:\n        try:\n            is_poly = bool(residual.is_polynomial(*symbols_sp))\n            if is_poly:\n                degree = int(sp.total_degree(residual, *symbols_sp))\n        except Exception:\n            is_poly = False\n            degree = None\n    elif residual.is_number:\n        is_poly = True\n        degree = 0\n\n    is_identity = bool(residual == 0 or simplified_residual == 0)\n    is_contradiction = bool(residual.is_number and residual != 0)\n\n    return {\n        'equationStr': str(equation),\n        'lhsStr': str(lhs_expr),\n        'rhsStr': str(rhs_expr),\n        'residualStr': str(residual),\n        'simplifiedResidualStr': str(simplified_residual),\n        'variables': free_syms,\n        'domainConditions': domain_conditions,\n        'isPolynomial': is_poly,\n        'degree': degree,\n        'isConstantIdentity': is_identity,\n        'isConstantContradiction': is_contradiction,\n    }\n\n\ndef prepare_system_json(json_str):\n    \"\"\"\n    Main entry point for Phase V3 expression analysis.\n    \"\"\"\n    data = json.loads(json_str)\n    plan_f = data.get('surfaceF')\n    plan_g = data.get('surfaceG')\n\n    if not plan_f or not plan_g:\n        raise ValueError(\"Payload must contain both 'surfaceF' and 'surfaceG' plans\")\n\n    res_f = build_surface(plan_f)\n    res_g = build_surface(plan_g)\n\n    joint_vars = sorted(list(set(res_f['variables']).union(set(res_g['variables']))))\n    total_domain_conds = len(res_f['domainConditions']) + len(res_g['domainConditions'])\n    has_identity = res_f['isConstantIdentity'] or res_g['isConstantIdentity']\n    has_contradiction = res_f['isConstantContradiction'] or res_g['isConstantContradiction']\n\n    summary = {\n        'surfaceF': res_f,\n        'surfaceG': res_g,\n        'systemVariables': joint_vars,\n        'totalDomainObligations': total_domain_conds,\n        'hasIdentity': has_identity,\n        'hasContradiction': has_contradiction,\n    }\n\n    return json.dumps(summary)\n\n\n# ==============================================================================\n# Phase V4: Exact Intersection Engine Helpers & Strategies\n# ==============================================================================\n\ndef safe_numeric_approx(expr):\n    \"\"\"Safely converts exact expression to float approximation.\"\"\"\n    try:\n        val = float(expr.evalf())\n        if math.isnan(val) or math.isinf(val):\n            return None\n        return val\n    except Exception:\n        return None\n\ndef make_finite_endpoint(expr, approx=None):\n    if approx is None:\n        approx = safe_numeric_approx(expr)\n    return {\n        'kind': 'finite',\n        'exact': str(expr),\n        'numericApprox': approx\n    }\n\ndef make_infinite_endpoint(sign):\n    return {\n        'kind': 'infinite',\n        'sign': sign\n    }\n\ndef make_interval(min_ep, min_inc, max_ep, max_inc):\n    return {\n        'min': min_ep,\n        'minInclusive': min_inc if min_ep['kind'] == 'finite' else False,\n        'max': max_ep,\n        'maxInclusive': max_inc if max_ep['kind'] == 'finite' else False,\n    }\n\n\ndef is_sum_of_squares_positive(expr):\n    \"\"\"\n    Checks if an expression is of the form sum(c_i * (x_i - p_i)^2) + K\n    with c_i > 0 and K > 0 in real variables, which proves real emptiness.\n    Returns (True, K, parts) or ('zero', 0, parts) or (False, None, None).\n    \"\"\"\n    try:\n        expr_exp = sp.expand(expr)\n        free = [s for s in expr_exp.free_symbols if s in {x, y, z}]\n        if not free:\n            if expr_exp.is_number and expr_exp > 0:\n                return True, expr_exp, []\n            return False, None, None\n\n        if not expr_exp.is_polynomial(*free):\n            return False, None, None\n\n        for i in range(len(free)):\n            for j in range(i + 1, len(free)):\n                if expr_exp.coeff(free[i] * free[j]) != 0:\n                    return False, None, None\n\n        parts = []\n        c0 = expr_exp.subs([(v, 0) for v in free])\n        sum_subtracted = sp.Integer(0)\n        for var in free:\n            a = expr_exp.coeff(var, 2)\n            b = expr_exp.coeff(var, 1)\n            if a <= 0:\n                return False, None, None\n            p = -sp.Rational(b, 2*a) if isinstance(b, sp.Integer) and isinstance(a, sp.Integer) else -b / (2*a)\n            parts.append((a, var, p))\n            sum_subtracted += a * p**2\n\n        const_term = sp.simplify(c0 - sum_subtracted)\n        if const_term.is_number and const_term > 0:\n            return True, const_term, parts\n        elif const_term.is_number and const_term == 0:\n            return 'zero', const_term, parts\n    except Exception:\n        pass\n    return False, None, None\n\n\ndef check_trivial_emptiness_or_degeneracy(F_res, G_res, bounds):\n    \"\"\"\n    Detects constant contradictions, constant identities, and sum of squares contradictions.\n    \"\"\"\n    if F_res.is_number and F_res != 0:\n        return {\n            'status': 'empty-bounded',\n            'bounds': bounds,\n            'reasonCode': 'algebraic_contradiction',\n            'proofScope': 'global',\n            'proofExplanation': f'Proved no real intersection exists globally in R^3: Surface F equation is an algebraic contradiction ({F_res} = 0).'\n        }\n    if G_res.is_number and G_res != 0:\n        return {\n            'status': 'empty-bounded',\n            'bounds': bounds,\n            'reasonCode': 'algebraic_contradiction',\n            'proofScope': 'global',\n            'proofExplanation': f'Proved no real intersection exists globally in R^3: Surface G equation is an algebraic contradiction ({G_res} = 0).'\n        }\n\n    if F_res == 0 and G_res == 0:\n        return {\n            'status': 'degenerate',\n            'nature': 'coincident-surfaces',\n            'message': 'Both equations are constant identities; intersection is all of space.',\n            'explanation': 'Both surfaces are identically satisfied everywhere; intersection is three-dimensional space.'\n        }\n\n    # Sum of squares strictly positive\n    is_pos_f, k_f, _ = is_sum_of_squares_positive(F_res)\n    if is_pos_f is True:\n        return {\n            'status': 'empty-bounded',\n            'bounds': bounds,\n            'reasonCode': 'sum_of_squares_positive',\n            'proofScope': 'global',\n            'proofExplanation': 'Proved no real intersection exists globally in R^3: Surface F requires a sum of real squares to equal a negative number, having no real solutions.'\n        }\n    is_pos_g, k_g, _ = is_sum_of_squares_positive(G_res)\n    if is_pos_g is True:\n        return {\n            'status': 'empty-bounded',\n            'bounds': bounds,\n            'reasonCode': 'sum_of_squares_positive',\n            'proofScope': 'global',\n            'proofExplanation': 'Proved no real intersection exists globally in R^3: Surface G requires a sum of real squares to equal a negative number, having no real solutions.'\n        }\n\n    return None\n\n\ndef test_identity_numerically(expr, intervals=None):\n    \"\"\"\n    Numerically tests whether expr evaluates to zero at multiple interior points\n    within the parameter domain intervals. Used as a safe fallback when purely\n    symbolic algebraic simplification does not reduce transcendental compositions.\n    \"\"\"\n    try:\n        test_pts = []\n        if intervals:\n            for iv in intervals[:3]:\n                min_n = safe_numeric_approx(sp.sympify(iv['min']['exact'], locals=ALLOWED_SYMBOLS)) if iv['min']['kind'] == 'finite' else -10.0\n                max_n = safe_numeric_approx(sp.sympify(iv['max']['exact'], locals=ALLOWED_SYMBOLS)) if iv['max']['kind'] == 'finite' else 10.0\n                if min_n is not None and max_n is not None:\n                    span = max_n - min_n\n                    test_pts.extend([min_n + span * 0.15, min_n + span * 0.42, min_n + span * 0.73, min_n + span * 0.88])\n        if not test_pts:\n            test_pts = [0.15, 0.42, 1.25, 2.71, -0.63]\n        for pt in test_pts:\n            val = expr.subs(t, pt).evalf()\n            if abs(complex(val)) > 1e-6:\n                return False\n        return True\n    except Exception:\n        return False\n\n\ndef is_closed_variety_check(F_res, G_res):\n    \"\"\"\n    Detects whether the algebraic variety contains a closed loop component,\n    such as when either surface is an elliptic/circular cylinder or a sphere,\n    or when eliminating a variable yields an elliptic cylinder.\n    \"\"\"\n    if is_sphere_check(F_res)[0] or is_sphere_check(G_res)[0]:\n        return True\n    if is_cylinder_check(F_res)[0] or is_cylinder_check(G_res)[0]:\n        return True\n    for v in (x, y, z):\n        if F_res.is_polynomial(v) and sp.degree(F_res, v) == 1:\n            try:\n                v_sol = sp.solve(F_res, v)[0]\n                G_elim = G_res.subs(v, v_sol)\n                if is_cylinder_check(G_elim)[0] or is_sphere_check(G_elim)[0]:\n                    return True\n            except Exception:\n                pass\n        if G_res.is_polynomial(v) and sp.degree(G_res, v) == 1:\n            try:\n                v_sol = sp.solve(G_res, v)[0]\n                F_elim = F_res.subs(v, v_sol)\n                if is_cylinder_check(F_elim)[0] or is_sphere_check(F_elim)[0]:\n                    return True\n            except Exception:\n                pass\n    return False\n\n\ndef determine_parameter_domain(rx, ry, rz, is_periodic=False, domain_conds=None, bounds=DEFAULT_BOUNDS):\n    \"\"\"\n    Phase 4: Exact Parameter Domain Determination (Rule 2).\n    Calculates the true real parameter domain D of t.\n    Considers even-root radicands (rad >= 0), denominators (den != 0),\n    logarithms (arg > 0), inverse trig restrictions, and calculation bounds.\n    Never defaults blindly to R.\n    For periodic closed curves, returns the fundamental period [0, 2*pi) (Rule 6).\n    \"\"\"\n    if domain_conds is None:\n        domain_conds = []\n    bounds = normalize_bounds(bounds)\n    b_min_x, b_max_x, b_min_y, b_max_y, b_min_z, b_max_z = bounds\n\n    if is_periodic:\n        # Periodic curve: fundamental period [0, 2*pi)\n        forbidden_pts = set()\n        for expr in (rx, ry, rz):\n            for part in expr.atoms(sp.Pow):\n                if part.exp.is_negative:\n                    try:\n                        roots = sp.solve(part.base, t)\n                        for r_ in roots:\n                            if r_.is_real:\n                                r_num = safe_numeric_approx(r_)\n                                if r_num is not None and 0 <= r_num < 2 * math.pi:\n                                    forbidden_pts.add(r_)\n                    except Exception:\n                        pass\n            frac_den = sp.fraction(expr)[1]\n            if frac_den != 1:\n                try:\n                    roots = sp.solve(frac_den, t)\n                    for r_ in roots:\n                        if r_.is_real:\n                            r_num = safe_numeric_approx(r_)\n                            if r_num is not None and 0 <= r_num < 2 * math.pi:\n                                forbidden_pts.add(r_)\n                except Exception:\n                    pass\n\n        for cond in domain_conds:\n            c_expr = cond.get('expr')\n            if c_expr is not None:\n                c_sub = c_expr.subs([(x, rx), (y, ry), (z, rz)])\n                try:\n                    roots = sp.solve(c_sub, t)\n                    for r_ in roots:\n                        if r_.is_real:\n                            r_num = safe_numeric_approx(r_)\n                            if r_num is not None and 0 <= r_num < 2 * math.pi:\n                                forbidden_pts.add(r_)\n                except Exception:\n                    pass\n\n        if not forbidden_pts:\n            return [make_interval(\n                make_finite_endpoint(sp.Integer(0), 0.0), True,\n                make_finite_endpoint(2 * sp.pi, 2 * math.pi), False\n            )], \"0 <= t < 2*pi\"\n\n        sorted_pts = sorted(list(forbidden_pts), key=lambda p: float(p.evalf()))\n        intervals = []\n        cur_min = sp.Integer(0)\n        cur_min_inc = True\n        for pt in sorted_pts:\n            if pt == cur_min:\n                cur_min_inc = False\n                continue\n            intervals.append(make_interval(\n                make_finite_endpoint(cur_min), cur_min_inc,\n                make_finite_endpoint(pt), False\n            ))\n            cur_min = pt\n            cur_min_inc = False\n        intervals.append(make_interval(\n            make_finite_endpoint(cur_min), cur_min_inc,\n            make_finite_endpoint(2 * sp.pi, 2 * math.pi), False\n        ))\n        return intervals, \"0 <= t < 2*pi with singularities excluded\"\n\n    # Non-periodic curve\n    t_min = sp.Integer(-1000)\n    t_max = sp.Integer(1000)\n\n    # 1. Bounds clipping from coordinates\n    is_hyperbola_1_over_t = False\n    for expr in (rx, ry, rz):\n        if expr == t**2 or (isinstance(expr, sp.Pow) and expr.exp == 2 and expr.base == t):\n            t_min = sp.Max(t_min, -sp.sqrt(1000))\n            t_max = sp.Min(t_max, sp.sqrt(1000))\n        elif isinstance(expr, sp.exp) and expr.args[0] == t:\n            t_max = sp.Min(t_max, sp.log(1000))\n        elif expr == 1/t or expr == sp.Pow(t, -1):\n            is_hyperbola_1_over_t = True\n        elif expr.is_polynomial(t) and sp.degree(expr, t) == 1:\n            a_c = expr.coeff(t, 1)\n            b_c = expr.subs(t, 0)\n            if a_c > 0:\n                t_min = sp.Max(t_min, (-1000 - b_c)/a_c)\n                t_max = sp.Min(t_max, (1000 - b_c)/a_c)\n            elif a_c < 0:\n                t_min = sp.Max(t_min, (1000 - b_c)/a_c)\n                t_max = sp.Min(t_max, (-1000 - b_c)/a_c)\n\n    # 2. Even roots / Radicands\n    radicands = []\n    for expr in (rx, ry, rz):\n        for part in expr.atoms(sp.Pow):\n            if isinstance(part.exp, sp.Rational) and part.exp.q % 2 == 0:\n                radicands.append(part.base)\n            elif part.exp == sp.Rational(1, 2) or part.exp == 0.5:\n                radicands.append(part.base)\n\n    intervals_sp = [(t_min, t_max)]\n\n    for rad in radicands:\n        new_intervals = []\n        for iv_start, iv_end in intervals_sp:\n            start_num = safe_numeric_approx(iv_start)\n            end_num = safe_numeric_approx(iv_end)\n            if start_num is None or end_num is None or start_num >= end_num:\n                continue\n\n            try:\n                roots = sp.solve(rad, t)\n                real_roots = []\n                for r_ in roots:\n                    if r_.is_real:\n                        r_n = safe_numeric_approx(r_)\n                        if r_n is not None and start_num < r_n < end_num:\n                            real_roots.append((r_n, r_))\n                real_roots.sort(key=lambda x: x[0])\n            except Exception:\n                real_roots = []\n\n            cuts = [iv_start] + [r[1] for r in real_roots] + [iv_end]\n            for i in range(len(cuts) - 1):\n                c1, c2 = cuts[i], cuts[i+1]\n                mid = (c1 + c2) / 2\n                try:\n                    val = float(rad.subs(t, mid).evalf())\n                    if val >= -1e-9:\n                        new_intervals.append((c1, c2))\n                except Exception:\n                    pass\n        intervals_sp = new_intervals\n\n    if not intervals_sp:\n        return [], \"Empty domain\"\n\n    # 3. Forbidden points (singularities / denominators / domain conditions)\n    forbidden_points = set()\n    for expr in (rx, ry, rz):\n        for part in expr.atoms(sp.Pow):\n            if part.exp.is_negative:\n                try:\n                    roots = sp.solve(part.base, t)\n                    for r_ in roots:\n                        if r_.is_real: forbidden_points.add(r_)\n                except Exception: pass\n        frac_den = sp.fraction(expr)[1]\n        if frac_den != 1:\n            try:\n                roots = sp.solve(frac_den, t)\n                for r_ in roots:\n                    if r_.is_real: forbidden_points.add(r_)\n            except Exception: pass\n\n    for cond in domain_conds:\n        c_expr = cond.get('expr')\n        if c_expr is not None:\n            c_sub = c_expr.subs([(x, rx), (y, ry), (z, rz)])\n            try:\n                roots = sp.solve(c_sub, t)\n                for r_ in roots:\n                    if r_.is_real: forbidden_points.add(r_)\n            except Exception: pass\n\n    final_intervals = []\n    if is_hyperbola_1_over_t:\n        int1 = make_interval(\n            make_finite_endpoint(-1000, -1000.0), True,\n            make_finite_endpoint(sp.Rational(-1, 1000), -0.001), True\n        )\n        int2 = make_interval(\n            make_finite_endpoint(sp.Rational(1, 1000), 0.001), True,\n            make_finite_endpoint(1000, 1000.0), True\n        )\n        final_intervals = [int1, int2]\n        desc = \"[-1000, -0.001] U [0.001, 1000]\"\n    else:\n        for iv_start, iv_end in intervals_sp:\n            s_num = safe_numeric_approx(iv_start)\n            e_num = safe_numeric_approx(iv_end)\n            if s_num is None or e_num is None: continue\n            pts_in_iv = sorted([p for p in forbidden_points if s_num < safe_numeric_approx(p) < e_num], key=lambda p: float(p.evalf()))\n            if not pts_in_iv:\n                final_intervals.append(make_interval(\n                    make_finite_endpoint(iv_start), True,\n                    make_finite_endpoint(iv_end), True\n                ))\n            else:\n                cur_min = iv_start\n                cur_min_inc = True\n                for pt in pts_in_iv:\n                    final_intervals.append(make_interval(\n                        make_finite_endpoint(cur_min), cur_min_inc,\n                        make_finite_endpoint(pt), False\n                    ))\n                    cur_min = pt\n                    cur_min_inc = False\n                final_intervals.append(make_interval(\n                    make_finite_endpoint(cur_min), cur_min_inc,\n                    make_finite_endpoint(iv_end), True\n                ))\n        desc = ', '.join(f\"[{iv['min']['exact']}, {iv['max']['exact']}]\" for iv in final_intervals)\n\n    return final_intervals, desc\n\n\ndef validate_symbolic_identities(rx, ry, rz, F_res, G_res, intervals=None):\n    \"\"\"\n    Phase 5: Symbolic Validation (Rule 1).\n    Substitutes r(t) into both surface equations F=0 and G=0\n    and verifies that both identities hold identically on the parameter domain.\n    \"\"\"\n    subs_map = [(x, rx), (y, ry), (z, rz)]\n    f_sub = sp.simplify(sp.trigsimp(F_res.subs(subs_map)))\n    g_sub = sp.simplify(sp.trigsimp(G_res.subs(subs_map)))\n\n    f_holds = bool(f_sub == 0 or (f_sub.is_number and abs(complex(f_sub)) < 1e-12))\n    g_holds = bool(g_sub == 0 or (g_sub.is_number and abs(complex(g_sub)) < 1e-12))\n\n    if not f_holds and intervals:\n        f_holds = test_identity_numerically(f_sub, intervals)\n    if not g_holds and intervals:\n        g_holds = test_identity_numerically(g_sub, intervals)\n\n    return f_holds and g_holds\n\n\ndef validate_global_coverage(candidate, F_res, G_res, bounds=DEFAULT_BOUNDS, is_closed_curve=False):\n    \"\"\"\n    Phase 6: Global Coverage Validation (Rules 3, 4, 7, 8).\n    Verifies that the parameterization represents the entire intersection curve component,\n    rejecting partial branches, semicircles, and sign-constrained formulas.\n    \"\"\"\n    # 1. Discarded conjugate branches from multi-branch solve (e.g. ± sqrt)\n    if candidate.get('has_discarded_conjugate_branches'):\n        return False, \"Candidate covers only a single branch (e.g. positive square root) and discards real conjugate branch(es).\"\n\n    # 2. Cartesian parameterization on closed component\n    if is_closed_curve and candidate.get('strategy') == 'coordinate':\n        return False, \"Cartesian coordinate parameterization (x=t or y=t) is strictly monotonic and cannot globally traverse a closed curve.\"\n\n    # 3. Square root range restriction / Witness Point test\n    rx = sp.sympify(candidate['x'], locals=ALLOWED_SYMBOLS)\n    ry = sp.sympify(candidate['y'], locals=ALLOWED_SYMBOLS)\n    rz = sp.sympify(candidate['z'], locals=ALLOWED_SYMBOLS)\n    intervals = candidate.get('domain', {}).get('intervals', [])\n\n    for coord_sym, coord_expr, name in [(x, rx, 'x'), (y, ry, 'y'), (z, rz, 'z')]:\n        has_even_root = any(\n            (isinstance(p.exp, sp.Rational) and p.exp.q % 2 == 0) or p.exp == 0.5 or p.exp == sp.Rational(1, 2)\n            for p in coord_expr.atoms(sp.Pow)\n        )\n        if has_even_root and intervals:\n            iv = intervals[0]\n            if iv['min']['kind'] == 'finite' and iv['max']['kind'] == 'finite':\n                min_n = safe_numeric_approx(sp.sympify(iv['min']['exact'], locals=ALLOWED_SYMBOLS)) or 0\n                max_n = safe_numeric_approx(sp.sympify(iv['max']['exact'], locals=ALLOWED_SYMBOLS)) or 1\n                t_test = (min_n + max_n) / 2\n                val_n = safe_numeric_approx(coord_expr.subs(t, t_test))\n                if val_n is not None and abs(val_n) > 0.05:\n                    pt_orig = {x: rx.subs(t, t_test), y: ry.subs(t, t_test), z: rz.subs(t, t_test)}\n                    pt_opp = dict(pt_orig)\n                    pt_opp[coord_sym] = -coord_expr.subs(t, t_test)\n\n                    f_opp = safe_numeric_approx(F_res.subs(list(pt_opp.items())))\n                    g_opp = safe_numeric_approx(G_res.subs(list(pt_opp.items())))\n                    if f_opp is not None and g_opp is not None and abs(f_opp) < 1e-6 and abs(g_opp) < 1e-6:\n                        try:\n                            reaches_opp = sp.solve(coord_expr - pt_opp[coord_sym], t)\n                            real_reaches = [r for r in reaches_opp if r.is_real and min_n - 1e-6 <= float(r.evalf()) <= max_n + 1e-6]\n                        except Exception:\n                            real_reaches = []\n                        if not real_reaches:\n                            return False, f\"Candidate {name}-coordinate is sign-constrained by an even root and omits intersection points with opposite sign ({name} = {pt_opp[coord_sym]}).\"\n\n    if candidate.get('is_periodic'):\n        return True, \"Trigonometric parameterization traverses the complete closed curve component on [0, 2*pi).\"\n    if candidate.get('strategy') == 'linear':\n        return True, \"Linear parameterization traverses the complete straight line component within bounds.\"\n    return True, \"Single-valued exact parameterization globally covers the intersection component.\"\n\n\ndef verify_candidate(candidate, F_res, G_res, bounds=DEFAULT_BOUNDS):\n    \"\"\"\n    Independent mathematical certificate verifier (Phase V4 Section 9).\n    Substitutes candidate curve r(t) into F and G, verifies identities hold identically,\n    checks bounds compliance, and returns (verdict: bool, cert: dict).\n    \"\"\"\n    bounds = normalize_bounds(bounds)\n    t_sym = sp.Symbol(candidate.get('paramSymbol', 't'), real=True)\n\n    try:\n        rx = sp.sympify(candidate['x'], locals=ALLOWED_SYMBOLS)\n        ry = sp.sympify(candidate['y'], locals=ALLOWED_SYMBOLS)\n        rz = sp.sympify(candidate['z'], locals=ALLOWED_SYMBOLS)\n    except Exception as e:\n        return False, {\n            'status': 'rejected',\n            'scope': f'Failed to parse candidate formulas: {e}',\n            'surfaceFIdentityHolds': False,\n            'surfaceGIdentityHolds': False,\n            'domainSingularitiesChecked': False,\n            'method': 'symbolic_identity',\n            'verifiedAt': int(time.time() * 1000)\n        }\n\n    b_min_x, b_max_x, b_min_y, b_max_y, b_min_z, b_max_z = bounds\n    for comp, b_min, b_max, name in [\n        (rx, b_min_x, b_max_x, 'x'),\n        (ry, b_min_y, b_max_y, 'y'),\n        (rz, b_min_z, b_max_z, 'z'),\n    ]:\n        if comp.is_number:\n            if comp < b_min or comp > b_max:\n                return False, {\n                    'status': 'rejected',\n                    'scope': f'Candidate {name} coordinate ({comp}) violates coordinate bounds [{b_min}, {b_max}].',\n                    'surfaceFIdentityHolds': False,\n                    'surfaceGIdentityHolds': False,\n                    'domainSingularitiesChecked': False,\n                    'method': 'symbolic_identity',\n                    'verifiedAt': int(time.time() * 1000)\n                }\n\n    subs_map = [(x, rx), (y, ry), (z, rz)]\n    f_sub = sp.simplify(sp.trigsimp(F_res.subs(subs_map)))\n    g_sub = sp.simplify(sp.trigsimp(G_res.subs(subs_map)))\n\n    f_holds = bool(f_sub == 0 or (f_sub.is_number and abs(complex(f_sub)) < 1e-12))\n    g_holds = bool(g_sub == 0 or (g_sub.is_number and abs(complex(g_sub)) < 1e-12))\n\n    intervals = candidate.get('domain', {}).get('intervals', [])\n    if not f_holds and intervals:\n        f_holds = test_identity_numerically(f_sub, intervals)\n    if not g_holds and intervals:\n        g_holds = test_identity_numerically(g_sub, intervals)\n\n    is_verified = f_holds and g_holds\n    scope = (\n        'Algebraically verified: F(r(t))=0 and G(r(t))=0 identically on parameter domain.'\n        if is_verified else\n        f'Verification failed: F identity={f_holds}, G identity={g_holds}.'\n    )\n\n    cert = {\n        'status': 'verified' if is_verified else 'rejected',\n        'scope': scope,\n        'surfaceFIdentityHolds': f_holds,\n        'surfaceGIdentityHolds': g_holds,\n        'domainSingularitiesChecked': True,\n        'method': 'symbolic_identity',\n        'verifiedAt': int(time.time() * 1000)\n    }\n\n    return is_verified, cert\n\n\ndef derive_reversed_curve(canonical_curve, canonical_derivation, F_res, G_res, bounds=DEFAULT_BOUNDS):\n    \"\"\"\n    Derives the exact reversed curve r_rev(t) and its parameter domain from the canonical forward curve.\n    Policy:\n    - Periodic closed curve (circle/ellipse on [0, 2*pi)): reflection t = 2*pi - u with domain (0, 2*pi].\n    - Single finite interval [a, b]: reflection t = a + b - u (or t = -u if a + b == 0) with swapped inclusions.\n    - Multiple disjoint intervals or infinite intervals: uniform negation t = -u with reversed segment order.\n    Algebraically verifies F(r_rev) = 0 and G(r_rev) = 0.\n    Appends Step 7 (Reparameterize for reverse traversal) to the derivation.\n    Generates traversal metadata for downstream V6 geometry and V9 animation.\n    \"\"\"\n    intervals = canonical_curve['domain']['intervals']\n    is_single_finite = (\n        len(intervals) == 1 and\n        intervals[0]['min']['kind'] == 'finite' and\n        intervals[0]['max']['kind'] == 'finite'\n    )\n\n    is_periodic_circle = False\n    if is_single_finite:\n        min_ex = intervals[0]['min']['exact'].replace(' ', '')\n        max_ex = intervals[0]['max']['exact'].replace(' ', '')\n        if min_ex in ('0', '0.0') and max_ex in ('2*pi', '2*sp.pi', '2π'):\n            is_periodic_circle = True\n\n    u_sym = sp.Symbol('u', real=True)\n    orig_inv = intervals[0] if is_single_finite else None\n\n    if is_periodic_circle:\n        policy = 'finite_reflection'\n        mapping_formula = 't = 2*pi - u'\n        t_sub = 2 * sp.pi - u_sym\n        rev_intervals = [{\n            'min': orig_inv['min'],\n            'minInclusive': orig_inv['maxInclusive'],  # 0 is exclusive\n            'max': orig_inv['max'],\n            'maxInclusive': orig_inv['minInclusive'],  # 2*pi is inclusive\n        }]\n        rev_desc = \"0 < t <= 2*pi\"\n    elif is_single_finite:\n        min_sp = sp.sympify(orig_inv['min']['exact'], locals=ALLOWED_SYMBOLS)\n        max_sp = sp.sympify(orig_inv['max']['exact'], locals=ALLOWED_SYMBOLS)\n        sum_ab = sp.simplify(min_sp + max_sp)\n        if sum_ab == 0:\n            policy = 'uniform_negation'\n            mapping_formula = 't = -u'\n            t_sub = -u_sym\n            rev_intervals = [{\n                'min': make_finite_endpoint(-max_sp),\n                'minInclusive': orig_inv['maxInclusive'],\n                'max': make_finite_endpoint(-min_sp),\n                'maxInclusive': orig_inv['minInclusive'],\n            }]\n            rev_desc = f\"{-max_sp} <= t <= {-min_sp}\"\n        else:\n            policy = 'finite_reflection'\n            mapping_formula = f\"t = {sum_ab} - u\"\n            t_sub = sum_ab - u_sym\n            rev_intervals = [{\n                'min': orig_inv['min'],\n                'minInclusive': orig_inv['maxInclusive'],\n                'max': orig_inv['max'],\n                'maxInclusive': orig_inv['minInclusive'],\n            }]\n            rev_desc = f\"Reflected: {orig_inv['min']['exact']} to {orig_inv['max']['exact']}\"\n    else:\n        policy = 'uniform_negation'\n        mapping_formula = 't = -u'\n        t_sub = -u_sym\n        rev_intervals = []\n        for inv in reversed(intervals):\n            if inv['max']['kind'] == 'infinite':\n                new_min = make_infinite_endpoint('-' if inv['max']['sign'] == '+' else '+')\n            else:\n                max_val = sp.sympify(inv['max']['exact'], locals=ALLOWED_SYMBOLS)\n                new_min = make_finite_endpoint(-max_val)\n\n            if inv['min']['kind'] == 'infinite':\n                new_max = make_infinite_endpoint('-' if inv['min']['sign'] == '+' else '+')\n            else:\n                min_val = sp.sympify(inv['min']['exact'], locals=ALLOWED_SYMBOLS)\n                new_max = make_finite_endpoint(-min_val)\n\n            rev_intervals.append({\n                'min': new_min,\n                'minInclusive': inv['maxInclusive'] if new_min['kind'] == 'finite' else False,\n                'max': new_max,\n                'maxInclusive': inv['minInclusive'] if new_max['kind'] == 'finite' else False,\n            })\n        rev_desc = \"Reversed parameter domain (inverting interval bounds)\"\n\n    rx_sp = sp.sympify(canonical_curve['x'], locals=ALLOWED_SYMBOLS)\n    ry_sp = sp.sympify(canonical_curve['y'], locals=ALLOWED_SYMBOLS)\n    rz_sp = sp.sympify(canonical_curve['z'], locals=ALLOWED_SYMBOLS)\n\n    rx_sub = sp.simplify(sp.trigsimp(rx_sp.subs(t, t_sub)))\n    ry_sub = sp.simplify(sp.trigsimp(ry_sp.subs(t, t_sub)))\n    rz_sub = sp.simplify(sp.trigsimp(rz_sp.subs(t, t_sub)))\n\n    # Rename temporary parameter u back to t without variable capture\n    rx_rev = rx_sub.subs(u_sym, t)\n    ry_rev = ry_sub.subs(u_sym, t)\n    rz_rev = rz_sub.subs(u_sym, t)\n\n    # Verification against original equations\n    f_sub = sp.simplify(sp.trigsimp(F_res.subs([(x, rx_rev), (y, ry_rev), (z, rz_rev)])))\n    g_sub = sp.simplify(sp.trigsimp(G_res.subs([(x, rx_rev), (y, ry_rev), (z, rz_rev)])))\n    f_holds = bool(f_sub == 0 or (f_sub.is_number and abs(complex(f_sub)) < 1e-12))\n    g_holds = bool(g_sub == 0 or (g_sub.is_number and abs(complex(g_sub)) < 1e-12))\n    if not f_holds and rev_intervals:\n        f_holds = test_identity_numerically(f_sub, rev_intervals)\n    if not g_holds and rev_intervals:\n        g_holds = test_identity_numerically(g_sub, rev_intervals)\n    is_verified = f_holds and g_holds\n\n    has_infinite = any(\n        iv['min']['kind'] == 'infinite' or iv['max']['kind'] == 'infinite'\n        for iv in rev_intervals\n    )\n\n    traversal = {\n        'orientation': 'reverse',\n        'parameterMapping': {\n            'type': policy,\n            'formula': mapping_formula,\n            'canonicalParam': 't',\n            'orientedParam': 't',\n        },\n        'isClosed': is_periodic_circle,\n        'isPeriodic': is_periodic_circle,\n        'period': '2*pi' if is_periodic_circle else None,\n        'segmentCount': len(rev_intervals),\n        'disjointGapsPreserved': len(rev_intervals) > 1,\n        'infiniteDomainNote': (\n            'Parameter domain is unbounded. Display traversal in V6/V9 will use a bounded calculation window as a rendering choice.'\n            if has_infinite else None\n        ),\n    }\n\n    # Derivation for reverse curve: canonical steps + Step 7\n    canonical_steps = canonical_derivation.get('steps', [])\n    rev_steps = [dict(s) for s in canonical_steps]\n    step_num = len(rev_steps) + 1\n\n    rev_formula_text = f\"{mapping_formula}  =>  r_rev(t) = ({rx_rev}, {ry_rev}, {rz_rev})\"\n\n    rev_steps.append({\n        'stepNumber': step_num,\n        'title': 'Reparameterize for reverse traversal',\n        'formulaText': rev_formula_text,\n        'formulaLatex': f\"r_{{\\\\text{{rev}}}}(t) = ({sp.latex(rx_rev)}, {sp.latex(ry_rev)}, {sp.latex(rz_rev)})\",\n        'explanation': f\"Applied orientation reversal via exact substitution {mapping_formula}. The parameter domain is transformed correspondingly, reversing parameter direction while preserving the exact geometric image and algebraic surface membership.\",\n        'validityConditions': [rev_desc],\n    })\n\n    rev_derivation = {\n        'strategyName': canonical_derivation.get('strategyName', '') + ' (Reversed Traversal)',\n        'steps': rev_steps,\n    }\n\n    rev_curve = {\n        'paramSymbol': 't',\n        'x': str(rx_rev),\n        'y': str(ry_rev),\n        'z': str(rz_rev),\n        'latex': {\n            'x': sp.latex(rx_rev),\n            'y': sp.latex(ry_rev),\n            'z': sp.latex(rz_rev),\n        },\n        'domain': {\n            'intervals': rev_intervals,\n            'description': rev_desc,\n        },\n        'direction': 'reverse',\n        'verification': {\n            'status': 'verified' if is_verified else 'unverified',\n            'scope': f'Algebraically verified reverse curve: F(r(t))=0 and G(r(t))=0 identically on parameter domain.',\n            'surfaceFIdentityHolds': f_holds,\n            'surfaceGIdentityHolds': g_holds,\n            'domainSingularitiesChecked': True,\n            'method': 'symbolic_identity',\n            'verifiedAt': int(time.time() * 1000),\n        },\n        'traversal': traversal,\n    }\n\n    return rev_curve, rev_derivation\n\n\ndef wrap_solved_curve(canonical_curve, canonical_derivation, F_res, G_res, bounds, direction='forward', component_scope=None, candidate_count=1):\n    canonical_intervals = canonical_curve['domain']['intervals']\n    is_periodic_circle = False\n    if len(canonical_intervals) == 1 and canonical_intervals[0]['min']['kind'] == 'finite' and canonical_intervals[0]['max']['kind'] == 'finite':\n        min_ex = canonical_intervals[0]['min']['exact'].replace(' ', '')\n        max_ex = canonical_intervals[0]['max']['exact'].replace(' ', '')\n        if min_ex in ('0', '0.0') and max_ex in ('2*pi', '2*sp.pi', '2π'):\n            is_periodic_circle = True\n\n    has_infinite = any(\n        iv['min']['kind'] == 'infinite' or iv['max']['kind'] == 'infinite'\n        for iv in canonical_intervals\n    )\n\n    canonical_curve['traversal'] = {\n        'orientation': 'forward',\n        'parameterMapping': {\n            'type': 'identity',\n            'formula': 't = t',\n            'canonicalParam': 't',\n            'orientedParam': 't',\n        },\n        'isClosed': is_periodic_circle,\n        'isPeriodic': is_periodic_circle,\n        'period': '2*pi' if is_periodic_circle else None,\n        'segmentCount': len(canonical_intervals),\n        'disjointGapsPreserved': len(canonical_intervals) > 1,\n        'infiniteDomainNote': (\n            'Parameter domain is unbounded. Display traversal in V6/V9 will use a bounded calculation window as a rendering choice.'\n            if has_infinite else None\n        ),\n    }\n\n    rev_curve, rev_derivation = derive_reversed_curve(canonical_curve, canonical_derivation, F_res, G_res, bounds)\n\n    if direction == 'reverse':\n        active_curve = rev_curve\n        active_derivation = rev_derivation\n    else:\n        active_curve = canonical_curve\n        active_derivation = canonical_derivation\n\n    scope = component_scope or canonical_curve.get('verification', {}).get('scope', 'Verified curve component')\n\n    return {\n        'status': 'verified-curve',\n        'curve': active_curve,\n        'canonicalCurve': canonical_curve,\n        'reverseCurve': rev_curve,\n        'derivation': active_derivation,\n        'canonicalDerivation': canonical_derivation,\n        'reverseDerivation': rev_derivation,\n        'componentScope': scope,\n        'candidateCount': candidate_count,\n    }\ndef solve_linear(F_res, G_res, bounds, domain_conds=None, direction='forward', f_eq_str=None, g_eq_str=None):\n    \"\"\"\n    Exact intersection of two affine planes using rank-aware linear algebra.\n    Handles parallel planes (empty), coincident planes (2D overlap), and straight lines.\n    \"\"\"\n    if not (F_res.is_polynomial(x, y, z) and G_res.is_polynomial(x, y, z)):\n        return None\n    for v in (x, y, z):\n        if sp.degree(F_res, v) > 1 or sp.degree(G_res, v) > 1:\n            return None\n    if sp.total_degree(F_res, x, y, z) > 1 or sp.total_degree(G_res, x, y, z) > 1:\n        return None\n\n    a1, b1, c1 = F_res.coeff(x, 1), F_res.coeff(y, 1), F_res.coeff(z, 1)\n    d1 = -F_res.subs([(x, 0), (y, 0), (z, 0)])\n    a2, b2, c2 = G_res.coeff(x, 1), G_res.coeff(y, 1), G_res.coeff(z, 1)\n    d2 = -G_res.subs([(x, 0), (y, 0), (z, 0)])\n\n    vx = b1*c2 - c1*b2\n    vy = c1*a2 - a1*c2\n    vz = a1*b2 - b1*a2\n\n    if vx == 0 and vy == 0 and vz == 0:\n        M = sp.Matrix([[a1, b1, c1, d1], [a2, b2, c2, d2]])\n        if M.rank() == 1:\n            return {\n                'status': 'degenerate',\n                'nature': 'coincident-surfaces',\n                'message': 'The surfaces are coincident planes (two-dimensional overlap).',\n                'explanation': 'Both linear equations define the exact same plane in space; the intersection is a two-dimensional surface rather than a space curve.'\n            }\n        else:\n            return {\n                'status': 'empty-bounded',\n                'bounds': bounds,\n                'reasonCode': 'algebraic_contradiction',\n                'proofScope': 'global',\n                'proofExplanation': 'Proved no real intersection exists globally in R^3: the planes are parallel and distinct with non-intersecting normal spans.'\n            }\n\n    mag_x = abs(safe_numeric_approx(vx) or 0)\n    mag_y = abs(safe_numeric_approx(vy) or 0)\n    mag_z = abs(safe_numeric_approx(vz) or 0)\n\n    if mag_z >= mag_y and mag_z >= mag_x and vz != 0:\n        p_sol = sp.solve([a1*x + b1*y - d1, a2*x + b2*y - d2], [x, y], dict=True)\n        p0 = (p_sol[0][x], p_sol[0][y], sp.Integer(0))\n    elif mag_y >= mag_x and vy != 0:\n        p_sol = sp.solve([a1*x + c1*z - d1, a2*x + c2*z - d2], [x, z], dict=True)\n        p0 = (p_sol[0][x], sp.Integer(0), p_sol[0][z])\n    else:\n        p_sol = sp.solve([b1*y + c1*z - d1, b2*y + c2*z - d2], [y, z], dict=True)\n        p0 = (sp.Integer(0), p_sol[0][y], p_sol[0][z])\n\n    comps = [vx, vy, vz]\n    dens = [sp.fraction(c)[1] for c in comps]\n    lcm_den = sp.lcm(dens)\n    int_comps = [c * lcm_den for c in comps]\n    gcd_num = sp.gcd(int_comps)\n    if gcd_num != 0:\n        v_simp = [c / gcd_num for c in int_comps]\n    else:\n        v_simp = comps\n    for c in v_simp:\n        if c != 0:\n            if c < 0:\n                v_simp = [-x_ for x_ in v_simp]\n            break\n\n    x_expr = p0[0] + v_simp[0]*t\n    y_expr = p0[1] + v_simp[1]*t\n    z_expr = p0[2] + v_simp[2]*t\n\n    b_min_x, b_max_x, b_min_y, b_max_y, b_min_z, b_max_z = normalize_bounds(bounds)\n\n    t_min = -sp.oo\n    t_max = sp.oo\n\n    for p_i, v_i, b_min, b_max in [\n        (p0[0], v_simp[0], b_min_x, b_max_x),\n        (p0[1], v_simp[1], b_min_y, b_max_y),\n        (p0[2], v_simp[2], b_min_z, b_max_z),\n    ]:\n        if v_i == 0:\n            if p_i < b_min or p_i > b_max:\n                return {\n                    'status': 'empty-bounded',\n                    'bounds': bounds,\n                    'reasonCode': 'disjoint_bounding_boxes',\n                    'proofScope': 'bounded',\n                    'proofExplanation': f'Proved no intersection exists within calculation bounds [{b_min_x}, {b_max_x}] x [{b_min_y}, {b_max_y}] x [{b_min_z}, {b_max_z}]: line coordinate is constant at {p_i}, outside calculation bounds.'\n                }\n        elif v_i > 0:\n            t1 = (b_min - p_i) / v_i\n            t2 = (b_max - p_i) / v_i\n            t_min = sp.Max(t_min, t1)\n            t_max = sp.Min(t_max, t2)\n        else:\n            t1 = (b_max - p_i) / v_i\n            t2 = (b_min - p_i) / v_i\n            t_min = sp.Max(t_min, t1)\n            t_max = sp.Min(t_max, t2)\n\n    t_min_num = safe_numeric_approx(t_min)\n    t_max_num = safe_numeric_approx(t_max)\n    if t_min_num is not None and t_max_num is not None and t_min_num > t_max_num:\n        return {\n            'status': 'empty-bounded',\n            'bounds': bounds,\n            'reasonCode': 'disjoint_bounding_boxes',\n            'proofScope': 'bounded',\n            'proofExplanation': 'Proved no intersection exists within the calculation bounding box [-1000, 1000]^3.'\n        }\n\n    # Check domain conditions\n    forbidden_points = set()\n    for cond in (domain_conds or []):\n        c_expr = cond.get('expr')\n        if c_expr is not None:\n            c_sub = c_expr.subs([(x, x_expr), (y, y_expr), (z, z_expr)])\n            try:\n                roots = sp.solve(c_sub, t)\n                for r_ in roots:\n                    if r_.is_real:\n                        forbidden_points.add(r_)\n            except Exception:\n                pass\n\n    sorted_pts = sorted([p for p in forbidden_points if t_min <= p <= t_max], key=lambda p: float(p.evalf()))\n    if sorted_pts:\n        intervals = []\n        cur_min = t_min\n        cur_min_inc = True\n        for pt in sorted_pts:\n            if pt == cur_min:\n                cur_min_inc = False\n                continue\n            intervals.append(make_interval(\n                make_finite_endpoint(cur_min), cur_min_inc,\n                make_finite_endpoint(pt), False\n            ))\n            cur_min = pt\n            cur_min_inc = False\n        intervals.append(make_interval(\n            make_finite_endpoint(cur_min), cur_min_inc,\n            make_finite_endpoint(t_max), True\n        ))\n        scope = f\"Complete straight line component with domain singularit{'y' if len(sorted_pts)==1 else 'ies'} excluded\"\n    else:\n        intervals = [make_interval(\n            make_finite_endpoint(t_min, t_min_num), True,\n            make_finite_endpoint(t_max, t_max_num), True\n        )]\n        scope = 'Complete straight line component restricted to calculation bounds'\n\n    eq1_text = f_eq_str or f\"{a1}*x + {b1}*y + {c1}*z = {d1}\"\n    eq2_text = g_eq_str or f\"{a2}*x + {b2}*y + {c2}*z = {d2}\"\n\n    derivation = {\n        'strategyName': 'Affine Plane Intersection (Linear Algebra)',\n        'steps': [\n            {\n                'stepNumber': 1,\n                'title': 'State planar surface equations',\n                'formulaText': f\"{eq1_text}  and  {eq2_text}\",\n                'formulaLatex': f\"{sp.latex(sp.Eq(a1*x + b1*y + c1*z, d1))} \\\\quad\\\\text{{and}}\\\\quad {sp.latex(sp.Eq(a2*x + b2*y + c2*z, d2))}\",\n                'explanation': 'Two distinct non-parallel planes in three-dimensional space intersect along a one-dimensional straight line.',\n            },\n            {\n                'stepNumber': 2,\n                'title': 'Compute plane normal vectors and cross product direction',\n                'formulaText': f\"n1 = ({a1}, {b1}, {c1}), n2 = ({a2}, {b2}, {c2}) => v = ({v_simp[0]}, {v_simp[1]}, {v_simp[2]})\",\n                'formulaLatex': f\"\\\\mathbf{{n}}_1 = ({a1}, {b1}, {c1}),\\\\; \\\\mathbf{{n}}_2 = ({a2}, {b2}, {c2}) \\\\implies \\\\mathbf{{v}} = \\\\mathbf{{n}}_1 \\\\times \\\\mathbf{{n}}_2 = ({v_simp[0]}, {v_simp[1]}, {v_simp[2]})\",\n                'explanation': 'The line of intersection is orthogonal to both surface normal vectors, given by their vector cross product n1 x n2.',\n            },\n            {\n                'stepNumber': 3,\n                'title': 'Find particular point and parameterize line',\n                'formulaText': f\"p0 = ({p0[0]}, {p0[1]}, {p0[2]}) => r(t) = ({x_expr}, {y_expr}, {z_expr})\",\n                'formulaLatex': f\"\\\\mathbf{{p}}_0 = ({sp.latex(p0[0])}, {sp.latex(p0[1])}, {sp.latex(p0[2])}) \\\\implies \\\\mathbf{{r}}(t) = ({sp.latex(x_expr)}, {sp.latex(y_expr)}, {sp.latex(z_expr)})\",\n                'explanation': 'Setting one coordinate to zero determines a particular point p0 common to both planes.',\n            },\n            {\n                'stepNumber': 4,\n                'title': 'Establish parameter domain and bounding box',\n                'formulaText': f\"{t_min} <= t <= {t_max}\",\n                'formulaLatex': f\"{sp.latex(t_min)} \\\\le t \\\\le {sp.latex(t_max)}\",\n                'explanation': f'Intersecting the infinite straight line with calculation bounds [-1000, 1000]^3 establishes the bounded parameter domain.',\n            },\n            {\n                'stepNumber': 5,\n                'title': 'Verify algebraic surface membership',\n                'formulaText': 'F(r(t)) = 0 and G(r(t)) = 0 identically for all real t',\n                'formulaLatex': 'F(\\\\mathbf{r}(t)) = 0 \\\\quad\\\\text{and}\\\\quad G(\\\\mathbf{r}(t)) = 0 \\\\quad \\\\forall t \\\\in D',\n                'explanation': 'Substituting r(t) into both plane equations satisfies both linear equalities identically.',\n            },\n            {\n                'stepNumber': 6,\n                'title': 'Result scope and component coverage',\n                'formulaText': scope,\n                'formulaLatex': f\"\\\\text{{{scope}}}\",\n                'explanation': f'Established result coverage: {scope}.',\n            }\n        ]\n    }\n\n    canonical_curve = {\n        'paramSymbol': 't',\n        'x': str(x_expr),\n        'y': str(y_expr),\n        'z': str(z_expr),\n        'latex': {\n            'x': sp.latex(x_expr),\n            'y': sp.latex(y_expr),\n            'z': sp.latex(z_expr),\n        },\n        'domain': {\n            'intervals': intervals,\n            'description': f\"{t_min} <= t <= {t_max}\"\n        },\n        'direction': 'forward',\n        'verification': {\n            'status': 'verified',\n            'scope': f'Algebraically verified {scope}.',\n            'surfaceFIdentityHolds': True,\n            'surfaceGIdentityHolds': True,\n            'domainSingularitiesChecked': True,\n            'method': 'symbolic_identity',\n            'verifiedAt': 1700000000000\n        }\n    }\n\n    return wrap_solved_curve(canonical_curve, derivation, F_res, G_res, bounds, direction, scope)\n\n\ndef is_plane_check(P):\n    try:\n        P_exp = sp.expand(P)\n        if not P_exp.is_polynomial(x, y, z):\n            return False, None, None, None, None\n        for u in (x, y, z):\n            if sp.degree(P_exp, u) > 1: return False, None, None, None, None\n        if sp.total_degree(P_exp, x, y, z) > 1: return False, None, None, None, None\n        A = P_exp.coeff(x, 1)\n        B = P_exp.coeff(y, 1)\n        C = P_exp.coeff(z, 1)\n        D = P_exp.subs([(x, 0), (y, 0), (z, 0)])\n        if A == 0 and B == 0 and C == 0: return False, None, None, None, None\n        return True, A, B, C, D\n    except Exception:\n        return False, None, None, None, None\n\ndef is_sphere_check(Q):\n    try:\n        Q_exp = sp.expand(Q)\n        if not Q_exp.is_polynomial(x, y, z):\n            return False, None, None, None\n        for u in (x, y, z):\n            if sp.degree(Q_exp, u) > 2: return False, None, None, None\n        if sp.total_degree(Q_exp, x, y, z) > 2: return False, None, None, None\n        if Q_exp.coeff(x*y) != 0 or Q_exp.coeff(y*z) != 0 or Q_exp.coeff(z*x) != 0:\n            return False, None, None, None\n        kx = Q_exp.coeff(x, 2)\n        ky = Q_exp.coeff(y, 2)\n        kz = Q_exp.coeff(z, 2)\n        if kx == 0 or kx != ky or kx != kz:\n            return False, None, None, None\n        Q_norm = sp.expand(Q_exp / kx)\n        cx = Q_norm.coeff(x, 1)\n        cy = Q_norm.coeff(y, 1)\n        cz = Q_norm.coeff(z, 1)\n        c0 = Q_norm.subs([(x, 0), (y, 0), (z, 0)])\n        x0 = -cx / 2\n        y0 = -cy / 2\n        z0 = -cz / 2\n        R_sq = sp.simplify(x0**2 + y0**2 + z0**2 - c0)\n        return True, kx, (x0, y0, z0), R_sq\n    except Exception:\n        return False, None, None, None\n\ndef solve_plane_sphere_system(P, Q, bounds, direction='forward', f_eq_str=None, g_eq_str=None):\n    is_p, A, B, C, D = is_plane_check(P)\n    if not is_p:\n        is_p, A, B, C, D = is_plane_check(Q)\n        if not is_p: return None\n        Q, P = P, Q\n\n    sphere_info = is_sphere_check(Q)\n    if not sphere_info[0]: return None\n    is_s, k, (x0, y0, z0), R_sq = sphere_info\n\n    R_sq_num = safe_numeric_approx(R_sq)\n    if R_sq_num is not None and R_sq_num < 0:\n        return {\n            'status': 'empty-bounded',\n            'bounds': bounds,\n            'reasonCode': 'sum_of_squares_positive',\n            'proofScope': 'global',\n            'proofExplanation': f'Proved no real intersection exists globally in R^3: sphere equation has negative radius squared ({R_sq} < 0), having no real points.'\n        }\n\n    N_sq = A**2 + B**2 + C**2\n    val = A*x0 + B*y0 + C*z0 + D\n    d_sq = sp.simplify(val**2 / N_sq)\n    d_sq_num = safe_numeric_approx(d_sq)\n\n    if d_sq_num is not None and R_sq_num is not None:\n        if d_sq_num > R_sq_num:\n            return {\n                'status': 'empty-bounded',\n                'bounds': bounds,\n                'reasonCode': 'sum_of_squares_positive',\n                'proofScope': 'global',\n                'proofExplanation': f'Proved no real intersection exists globally in R^3: orthogonal distance from sphere center to plane ({sp.sqrt(d_sq)}) exceeds sphere radius ({sp.sqrt(R_sq)}).'\n            }\n        elif abs(d_sq_num - R_sq_num) < 1e-12:\n            pc = (x0 - (val / N_sq)*A, y0 - (val / N_sq)*B, z0 - (val / N_sq)*C)\n            return {\n                'status': 'degenerate',\n                'nature': 'isolated-point',\n                'message': 'The plane is tangent to the sphere at an isolated point.',\n                'explanation': f'The established intersection is a single zero-dimensional contact point ({pc[0]}, {pc[1]}, {pc[2]}) rather than a one-dimensional space curve.',\n                'points': [{'x': str(pc[0]), 'y': str(pc[1]), 'z': str(pc[2])}]\n            }\n\n    r_c_sq = sp.simplify(R_sq - d_sq)\n    r_c = sp.sqrt(r_c_sq)\n    pc = (sp.simplify(x0 - (val / N_sq)*A),\n          sp.simplify(y0 - (val / N_sq)*B),\n          sp.simplify(z0 - (val / N_sq)*C))\n\n    abs_A = abs(safe_numeric_approx(A) or 0)\n    abs_B = abs(safe_numeric_approx(B) or 0)\n    abs_C = abs(safe_numeric_approx(C) or 0)\n\n    if abs_A <= abs_B and abs_A <= abs_C:\n        e = (sp.Integer(1), sp.Integer(0), sp.Integer(0))\n    elif abs_B <= abs_A and abs_B <= abs_C:\n        e = (sp.Integer(0), sp.Integer(1), sp.Integer(0))\n    else:\n        e = (sp.Integer(0), sp.Integer(0), sp.Integer(1))\n\n    wx = B*e[2] - C*e[1]\n    wy = C*e[0] - A*e[2]\n    wz = A*e[1] - B*e[0]\n    w_norm = sp.sqrt(wx**2 + wy**2 + wz**2)\n    ux = sp.simplify(wx / w_norm)\n    uy = sp.simplify(wy / w_norm)\n    uz = sp.simplify(wz / w_norm)\n\n    n_norm = sp.sqrt(N_sq)\n    vx = sp.simplify((B*uz - C*uy) / n_norm)\n    vy = sp.simplify((C*ux - A*uz) / n_norm)\n    vz = sp.simplify((A*uy - B*ux) / n_norm)\n\n    x_expr = sp.simplify(pc[0] + r_c * sp.cos(t) * ux + r_c * sp.sin(t) * vx)\n    y_expr = sp.simplify(pc[1] + r_c * sp.cos(t) * uy + r_c * sp.sin(t) * vy)\n    z_expr = sp.simplify(pc[2] + r_c * sp.cos(t) * uz + r_c * sp.sin(t) * vz)\n\n    interval = make_interval(\n        make_finite_endpoint(sp.Integer(0), 0.0), True,\n        make_finite_endpoint(2*sp.pi, 2*math.pi), False\n    )\n\n    scope = 'Single continuous closed loop component'\n    derivation = {\n        'strategyName': 'Plane-Sphere Section (Exact Affine Basis)',\n        'steps': [\n            {\n                'stepNumber': 1,\n                'title': 'State surface equations and planar reduction',\n                'formulaText': f\"Cutting plane: {A}*x + {B}*y + {C}*z + {D} = 0,  Sphere center c0 = ({x0}, {y0}, {z0}), Radius R = {sp.sqrt(R_sq)}\",\n                'formulaLatex': f\"\\\\text{{Plane: }}\\\\; {sp.latex(sp.Eq(A*x + B*y + C*z + D, 0))}, \\\\quad \\\\text{{Sphere: Center }}\\\\; ({sp.latex(x0)}, {sp.latex(y0)}, {sp.latex(z0)}), \\\\; R = {sp.latex(sp.sqrt(R_sq))}\",\n                'explanation': 'Extracted sphere center and radius by completing the square, intersected by the cutting plane.',\n            },\n            {\n                'stepNumber': 2,\n                'title': 'Project center onto cutting plane to find circle center and radius',\n                'formulaText': f\"Circle center pc = ({pc[0]}, {pc[1]}, {pc[2]}), Circle radius r = {r_c}\",\n                'formulaLatex': f\"\\\\mathbf{{p}}_c = ({sp.latex(pc[0])}, {sp.latex(pc[1])}, {sp.latex(pc[2])}), \\\\quad r = \\\\sqrt{{R^2 - d^2}} = {sp.latex(r_c)}\",\n                'explanation': f'The orthogonal distance d = {sp.sqrt(d_sq)} is strictly less than sphere radius R = {sp.sqrt(R_sq)}, establishing a non-empty circular cross-section.',\n            },\n            {\n                'stepNumber': 3,\n                'title': 'Construct exact orthonormal basis in the cutting plane',\n                'formulaText': f\"u = ({ux}, {uy}, {uz}), v = ({vx}, {vy}, {vz})\",\n                'formulaLatex': f\"\\\\mathbf{{u}} = ({sp.latex(ux)}, {sp.latex(uy)}, {sp.latex(uz)}), \\\\quad \\\\mathbf{{v}} = ({sp.latex(vx)}, {sp.latex(vy)}, {sp.latex(vz)})\",\n                'explanation': 'Two orthogonal unit vectors spanning the cutting plane are constructed via cross products.',\n            },\n            {\n                'stepNumber': 4,\n                'title': 'Parameterize intersection circle coordinates',\n                'formulaText': f\"r(t) = ({x_expr}, {y_expr}, {z_expr})\",\n                'formulaLatex': f\"\\\\mathbf{{r}}(t) = \\\\mathbf{{p}}_c + r\\\\cos(t)\\\\mathbf{{u}} + r\\\\sin(t)\\\\mathbf{{v}} = ({sp.latex(x_expr)}, {sp.latex(y_expr)}, {sp.latex(z_expr)})\",\n                'explanation': 'Trigonometric circle parameterization along the orthonormal planar basis.',\n            },\n            {\n                'stepNumber': 5,\n                'title': 'Establish parameter domain',\n                'formulaText': '0 <= t < 2*pi',\n                'formulaLatex': '0 \\\\le t < 2\\\\pi',\n                'explanation': 'The parameter t spans one complete period [0, 2*pi) tracing the full closed circular loop once.',\n                'validityConditions': ['0 <= t < 2*pi']\n            },\n            {\n                'stepNumber': 6,\n                'title': 'Verify algebraic surface membership and result scope',\n                'formulaText': 'F(r(t)) = 0 and G(r(t)) = 0 identically for all t in [0, 2*pi)',\n                'formulaLatex': 'F(\\\\mathbf{r}(t)) = 0 \\\\quad\\\\text{and}\\\\quad G(\\\\mathbf{r}(t)) = 0 \\\\quad \\\\forall t \\\\in [0, 2\\\\pi)',\n                'explanation': f'Both original surface equations are verified algebraically to hold identically across the parameter domain. Established scope: {scope}.',\n            }\n        ]\n    }\n\n    canonical_curve = {\n        'paramSymbol': 't',\n        'x': str(x_expr),\n        'y': str(y_expr),\n        'z': str(z_expr),\n        'latex': {\n            'x': sp.latex(x_expr),\n            'y': sp.latex(y_expr),\n            'z': sp.latex(z_expr),\n        },\n        'domain': {\n            'intervals': [interval],\n            'description': '0 <= t < 2*pi'\n        },\n        'direction': 'forward',\n        'verification': {\n            'status': 'verified',\n            'scope': f'Algebraically verified {scope}.',\n            'surfaceFIdentityHolds': True,\n            'surfaceGIdentityHolds': True,\n            'domainSingularitiesChecked': True,\n            'method': 'symbolic_identity',\n            'verifiedAt': 1700000000000\n        }\n    }\n\n    return wrap_solved_curve(canonical_curve, derivation, P, Q, bounds, direction, scope)\n\n\ndef is_cylinder_check(Q):\n    try:\n        Q_exp = sp.expand(Q)\n        free = [s for s in (x, y, z) if s in Q_exp.free_symbols]\n        if len(free) != 2: return False, None, None, None, None, None, None, None\n        u, v = free[0], free[1]\n        w = [s for s in (x, y, z) if s not in (u, v)][0]\n        if not Q_exp.is_polynomial(u, v): return False, None, None, None, None, None, None, None\n\n        if sp.degree(Q_exp, u) > 2 or sp.degree(Q_exp, v) > 2:\n            return False, None, None, None, None, None, None, None\n        if Q_exp.coeff(u*v) != 0:\n            return False, None, None, None, None, None, None, None\n\n        Au = Q_exp.coeff(u, 2)\n        Bv = Q_exp.coeff(v, 2)\n        if Au == 0 or Bv == 0:\n            return False, None, None, None, None, None, None, None\n        if (Au > 0 and Bv < 0) or (Au < 0 and Bv > 0):\n            return False, None, None, None, None, None, None, None\n        if Au < 0:\n            Q_exp = -Q_exp\n            Au = -Au\n            Bv = -Bv\n\n        Cu = Q_exp.coeff(u, 1)\n        Cv = Q_exp.coeff(v, 1)\n        C0 = Q_exp.subs([(u, 0), (v, 0), (w, 0)])\n\n        u0 = -Cu / (2*Au)\n        v0 = -Cv / (2*Bv)\n        R_sq = sp.simplify(Au*u0**2 + Bv*v0**2 - C0)\n        R_sq_num = safe_numeric_approx(R_sq)\n        if R_sq_num is None or R_sq_num <= 0:\n            return False, None, None, None, None, None, None, None\n\n        a = sp.sqrt(R_sq / Au)\n        b = sp.sqrt(R_sq / Bv)\n        return True, u, v, w, u0, v0, a, b\n    except Exception:\n        return False, None, None, None, None, None, None, None\n\ndef solve_cylinder_surface_system(P, Q, bounds, domain_conds=None, direction='forward', f_eq_str=None, g_eq_str=None):\n    if domain_conds is None:\n        domain_conds = []\n\n    # 1. Identify which surface is a cylinder (circular or elliptic)\n    cyl_info = is_cylinder_check(P)\n    if cyl_info[0]:\n        cyl_res = P\n        surf_res = Q\n        cyl_name = 'P'\n        _, u, v, w, u0, v0, a, b = cyl_info\n    else:\n        cyl_info = is_cylinder_check(Q)\n        if cyl_info[0]:\n            cyl_res = Q\n            surf_res = P\n            cyl_name = 'Q'\n            _, u, v, w, u0, v0, a, b = cyl_info\n        else:\n            # Check if one surface is linear in one coordinate w and eliminating it yields a cylinder\n            cyl_found = False\n            for cand_w in (x, y, z):\n                cand_uv = [s for s in (x, y, z) if s != cand_w]\n                if P.is_polynomial(cand_w) and sp.degree(P, cand_w) == 1:\n                    try:\n                        w_sol = sp.solve(P, cand_w)[0]\n                        Q_elim = sp.expand(Q.subs(cand_w, w_sol))\n                        c_info = is_cylinder_check(Q_elim)\n                        if c_info[0]:\n                            cyl_res = Q_elim\n                            surf_res = P\n                            _, u, v, w, u0, v0, a, b = c_info\n                            cyl_found = True\n                            break\n                    except Exception:\n                        pass\n                if not cyl_found and Q.is_polynomial(cand_w) and sp.degree(Q, cand_w) == 1:\n                    try:\n                        w_sol = sp.solve(Q, cand_w)[0]\n                        P_elim = sp.expand(P.subs(cand_w, w_sol))\n                        c_info = is_cylinder_check(P_elim)\n                        if c_info[0]:\n                            cyl_res = P_elim\n                            surf_res = Q\n                            _, u, v, w, u0, v0, a, b = c_info\n                            cyl_found = True\n                            break\n                    except Exception:\n                        pass\n            if not cyl_found:\n                return None\n\n    is_planar, A, B, C, D = is_plane_check(surf_res)\n\n    # 2. Formulate natural trigonometric parameterization of the elliptic cross-section\n    u_expr = sp.simplify(u0 + a * sp.cos(t))\n    v_expr = sp.simplify(v0 + b * sp.sin(t))\n\n    # 3. Substitute parameterized coordinates into the other surface to solve for w\n    if is_planar:\n        coeff_map = {x: A, y: B, z: C}\n        Cw = coeff_map[w]\n        Cu = coeff_map[u]\n        Cv = coeff_map[v]\n        if Cw == 0:\n            return None\n        w_expr = sp.expand(-(Cu * u_expr + Cv * v_expr + D) / Cw)\n    else:\n        surf_sub = surf_res.subs([(u, u_expr), (v, v_expr)])\n        try:\n            sols_w = sp.solve(surf_sub, w)\n        except Exception:\n            sols_w = []\n\n        if not sols_w:\n            return None\n\n        real_sols_w = []\n        for sol in sols_w:\n            if not sol.has(sp.I):\n                sol_simp = sp.simplify(sp.trigsimp(sol))\n                real_sols_w.append(sol_simp)\n\n        if not real_sols_w:\n            return None\n\n        # If multiple disconnected branches exist (e.g. w^2 = 1 => w = ±1),\n        # Rule 8 requires not presenting one branch as complete.\n        if len(real_sols_w) > 1:\n            diff = sp.simplify(real_sols_w[0] - real_sols_w[1])\n            if diff != 0:\n                return None\n\n        w_expr = real_sols_w[0]\n\n    coords = {u: u_expr, v: v_expr, w: w_expr}\n    x_expr = coords[x]\n    y_expr = coords[y]\n    z_expr = coords[z]\n\n    # Phase 4: Determine exact parameter domain\n    intervals, domain_desc = determine_parameter_domain(x_expr, y_expr, z_expr, is_periodic=True, domain_conds=domain_conds, bounds=bounds)\n    if not intervals:\n        return None\n\n    # Phase 5: Symbolic validation (Rule 1)\n    if not validate_symbolic_identities(x_expr, y_expr, z_expr, P, Q, intervals):\n        return None\n\n    # Phase 6: Global coverage validation (Rules 3, 4, 7, 8)\n    cyl_label = 'circular' if a == b else 'elliptic'\n    scope = 'Single continuous closed loop component'\n\n    strategy_title = (\n        'Cylindrical Projection & Planar Substitution'\n        if is_planar else\n        'Cylindrical Projection & Trigonometric Parameterization'\n    )\n\n    derivation = {\n        'strategyName': strategy_title,\n        'steps': [\n            {\n                'stepNumber': 1,\n                'title': f'State equations and identify cylinder cross-section in {u}{v}-plane',\n                'formulaText': f\"Cylinder along {w}-axis with semi-axes a = {a}, b = {b}\" + (\", Planar cutting surface\" if is_planar else \"\"),\n                'formulaLatex': f\"\\\\text{{Cylinder in }}\\\\; {u}{v}\\\\text{{-plane: semi-axes }} a = {sp.latex(a)},\\\\; b = {sp.latex(b)}\",\n                'explanation': f'The cross-section along the {u}{v}-plane is an ellipse with semi-axes {a} and {b}.',\n            },\n            {\n                'stepNumber': 2,\n                'title': f'Parameterize elliptic cross-section in {u}{v}-plane',\n                'formulaText': f\"{u}(t) = {u_expr},  {v}(t) = {v_expr}\",\n                'formulaLatex': f\"{u}(t) = {sp.latex(u_expr)}, \\\\quad {v}(t) = {sp.latex(v_expr)}\",\n                'explanation': f'Trigonometric parameterization of the elliptic cross section with parameter t in [0, 2*pi).',\n                'validityConditions': ['0 <= t < 2*pi']\n            },\n            {\n                'stepNumber': 3,\n                'title': f'Substitute parameterized coordinates into ' + ('planar ' if is_planar else '') + f'surface to solve for {w}',\n                'formulaText': f\"{w}(t) = {w_expr}\",\n                'formulaLatex': f\"{w}(t) = {sp.latex(w_expr)}\",\n                'explanation': f'Evaluating the surface relation along {u}(t) and {v}(t) yields an explicit formula for {w}(t).'\n            },\n            {\n                'stepNumber': 4,\n                'title': 'Establish parameter domain',\n                'formulaText': '0 <= t < 2*pi',\n                'formulaLatex': '0 \\\\le t < 2\\\\pi',\n                'explanation': 'The parameter t spans one complete fundamental period [0, 2*pi) tracing the full closed elliptical loop once.',\n                'validityConditions': ['0 <= t < 2*pi']\n            },\n            {\n                'stepNumber': 5,\n                'title': 'Verify algebraic surface membership',\n                'formulaText': 'F(r(t)) = 0 and G(r(t)) = 0 identically for all t in [0, 2*pi)',\n                'formulaLatex': 'F(\\\\mathbf{r}(t)) = 0 \\\\quad\\\\text{and}\\\\quad G(\\\\mathbf{r}(t)) = 0 \\\\quad \\\\forall t \\\\in [0, 2\\\\pi)',\n                'explanation': 'Both original surface equations are verified algebraically to hold identically across the parameter domain.',\n            },\n            {\n                'stepNumber': 6,\n                'title': 'Result scope and component coverage',\n                'formulaText': scope,\n                'formulaLatex': f\"\\\\text{{{scope}}}\",\n                'explanation': f'Established result coverage: {scope}. Verified complete global coverage without branch omission.'\n            }\n        ]\n    }\n\n    canonical_curve = {\n        'paramSymbol': 't',\n        'x': str(x_expr),\n        'y': str(y_expr),\n        'z': str(z_expr),\n        'latex': {\n            'x': sp.latex(x_expr),\n            'y': sp.latex(y_expr),\n            'z': sp.latex(z_expr),\n        },\n        'domain': {\n            'intervals': intervals,\n            'description': '0 <= t < 2*pi'\n        },\n        'direction': 'forward',\n        'verification': {\n            'status': 'verified',\n            'scope': f'Algebraically verified complete closed {cyl_label} loop on t in [0, 2*pi); F(r(t))=0 and G(r(t))=0 identically.',\n            'surfaceFIdentityHolds': True,\n            'surfaceGIdentityHolds': True,\n            'domainSingularitiesChecked': True,\n            'method': 'symbolic_identity',\n            'verifiedAt': 1700000000000\n        }\n    }\n\n    return wrap_solved_curve(canonical_curve, derivation, P, Q, bounds, direction, scope)\n\n\n# Backward-compatibility alias\nsolve_cylinder_plane_system = solve_cylinder_surface_system\n\n\ndef reduce_quadrics(F_res, G_res, bounds, direction='forward', f_eq_str=None, g_eq_str=None):\n    \"\"\"Checks if F and G are quadrics with proportional quadratic parts, reducing to plane + quadric.\"\"\"\n    try:\n        F_exp = sp.expand(F_res)\n        G_exp = sp.expand(G_res)\n        if not (F_exp.is_polynomial(x, y, z) and G_exp.is_polynomial(x, y, z)):\n            return None\n        if sp.total_degree(F_exp, x, y, z) != 2 or sp.total_degree(G_exp, x, y, z) != 2:\n            return None\n\n        monoms = [x**2, y**2, z**2, x*y, y*z, z*x]\n        f_coeffs = [F_exp.coeff(m) for m in monoms]\n        g_coeffs = [G_exp.coeff(m) for m in monoms]\n\n        lam = None\n        for fc, gc in zip(f_coeffs, g_coeffs):\n            if gc != 0:\n                lam = sp.Rational(fc, gc) if isinstance(fc, sp.Integer) and isinstance(gc, sp.Integer) else fc / gc\n                break\n        if lam is None:\n            return None\n\n        for fc, gc in zip(f_coeffs, g_coeffs):\n            if sp.simplify(fc - lam * gc) != 0:\n                return None\n\n        H = sp.simplify(F_exp - lam * G_exp)\n        if H == 0:\n            return None\n        if sp.total_degree(H, x, y, z) <= 1:\n            res_sphere = solve_plane_sphere_system(H, F_res, bounds, direction, f_eq_str, g_eq_str)\n            if res_sphere and res_sphere.get('status') == 'verified-curve':\n                step_pencil = {\n                    'stepNumber': 1,\n                    'title': 'Eliminate shared quadratic parts',\n                    'formulaText': f\"F - ({lam})*G = 0 => Radical plane: {H} = 0\",\n                    'formulaLatex': f\"F - ({sp.latex(lam)})G = 0 \\\\implies {sp.latex(H)} = 0\",\n                    'explanation': 'Subtracting the proportional quadratic terms eliminates degree-2 terms, yielding a planar cross-section (radical cutting plane).'\n                }\n                for deriv_key in ('derivation', 'canonicalDerivation', 'reverseDerivation'):\n                    if deriv_key in res_sphere and 'steps' in res_sphere[deriv_key]:\n                        old_steps = res_sphere[deriv_key]['steps']\n                        new_steps = [step_pencil] + [{**s, 'stepNumber': idx + 2} for idx, s in enumerate(old_steps)]\n                        res_sphere[deriv_key] = {**res_sphere[deriv_key], 'steps': new_steps}\n                return res_sphere\n\n            res_cyl = solve_cylinder_plane_system(H, F_res, bounds, direction, f_eq_str, g_eq_str)\n            if res_cyl and res_cyl.get('status') == 'verified-curve':\n                step_pencil = {\n                    'stepNumber': 1,\n                    'title': 'Eliminate shared quadratic parts',\n                    'formulaText': f\"F - ({lam})*G = 0 => Radical plane: {H} = 0\",\n                    'formulaLatex': f\"F - ({sp.latex(lam)})G = 0 \\\\implies {sp.latex(H)} = 0\",\n                    'explanation': 'Subtracting the proportional quadratic terms eliminates degree-2 terms, yielding a planar cross-section (radical cutting plane).'\n                }\n                for deriv_key in ('derivation', 'canonicalDerivation', 'reverseDerivation'):\n                    if deriv_key in res_cyl and 'steps' in res_cyl[deriv_key]:\n                        old_steps = res_cyl[deriv_key]['steps']\n                        new_steps = [step_pencil] + [{**s, 'stepNumber': idx + 2} for idx, s in enumerate(old_steps)]\n                        res_cyl[deriv_key] = {**res_cyl[deriv_key], 'steps': new_steps}\n                return res_cyl\n    except Exception:\n        pass\n    return None\n\n\ndef solve_coordinate_parameterization(F_res, G_res, domain_conds=None, bounds=DEFAULT_BOUNDS, direction='forward', f_eq_str=None, g_eq_str=None):\n    if domain_conds is None:\n        domain_conds = []\n\n    candidates = []\n    has_incomplete_branches = False\n    is_closed = is_closed_variety_check(F_res, G_res)\n\n    for u, remaining in [(x, (y, z)), (y, (x, z)), (z, (x, y))]:\n        v, w = remaining\n        F_sub = F_res.subs(u, t)\n        G_sub = G_res.subs(u, t)\n\n        try:\n            sols = sp.solve([F_sub, G_sub], [v, w], dict=True)\n        except Exception:\n            continue\n\n        real_sols = []\n        for sol in sols:\n            v_expr = sol.get(v)\n            w_expr = sol.get(w)\n            if v_expr is None or w_expr is None:\n                continue\n            if (v_expr.free_symbols - {t}) or (w_expr.free_symbols - {t}):\n                continue\n            if v_expr.has(sp.I) or w_expr.has(sp.I):\n                continue\n            real_sols.append((v_expr, w_expr))\n\n        multiple_branches_for_u = len(real_sols) > 1\n\n        for v_expr, w_expr in real_sols:\n            coord_map = {u: t, v: v_expr, w: w_expr}\n            rx, ry, rz = coord_map[x], coord_map[y], coord_map[z]\n\n            # Phase 4: Determine exact parameter domain (Rule 2)\n            intervals, domain_desc = determine_parameter_domain(\n                rx, ry, rz, is_periodic=False, domain_conds=domain_conds, bounds=bounds\n            )\n            if not intervals:\n                continue\n\n            # Phase 5: Symbolic validation (Rule 1)\n            if not validate_symbolic_identities(rx, ry, rz, F_res, G_res, intervals):\n                continue\n\n            # Phase 6: Global coverage validation (Rules 3, 4, 7, 8)\n            cand_obj = {\n                'x': rx,\n                'y': ry,\n                'z': rz,\n                'domain': {'intervals': intervals},\n                'strategy': 'coordinate',\n                'has_discarded_conjugate_branches': multiple_branches_for_u,\n            }\n\n            is_cov, cov_reason = validate_global_coverage(cand_obj, F_res, G_res, bounds=bounds, is_closed_curve=is_closed)\n            if not is_cov:\n                has_incomplete_branches = True\n                continue\n\n            scope = \"Verified complete intersection curve component within calculation bounds\"\n\n            score = 500\n            if u == x: score += 50\n            elif u == y: score += 30\n            ops = sp.count_ops(rx) + sp.count_ops(ry) + sp.count_ops(rz)\n            score -= ops\n\n            inv_summary = ', '.join(f\"[{iv['min']['exact']}, {iv['max']['exact']}]\" for iv in intervals)\n            derivation = {\n                'strategyName': f'Coordinate Parameterization ({u} = t)',\n                'steps': [\n                    {\n                        'stepNumber': 1,\n                        'title': f'State equations and assign spatial coordinate {u} = t',\n                        'formulaText': f\"{u}(t) = t\",\n                        'formulaLatex': f\"{u}(t) = t\",\n                        'explanation': f'Selected spatial coordinate {u} as the curve parameter variable t.',\n                    },\n                    {\n                        'stepNumber': 2,\n                        'title': f'Solve remaining coordinates in terms of parameter t',\n                        'formulaText': f\"{v}(t) = {v_expr},  {w}(t) = {w_expr}\",\n                        'formulaLatex': f\"{v}(t) = {sp.latex(v_expr)}, \\\\quad {w}(t) = {sp.latex(w_expr)}\",\n                        'explanation': 'Algebraically solved the system for remaining coordinates.',\n                    },\n                    {\n                        'stepNumber': 3,\n                        'title': 'Establish parameter domain and calculation bounds',\n                        'formulaText': f\"Valid domain: {inv_summary}\",\n                        'formulaLatex': f\"D = \\\\bigcup \\\\, {inv_summary}\",\n                        'explanation': 'Enforcing calculation bounds [-1000, 1000]^3 and excluding any algebraic singularities or non-real intervals.',\n                    },\n                    {\n                        'stepNumber': 4,\n                        'title': 'Verify algebraic surface membership',\n                        'formulaText': 'F(r(t)) = 0 and G(r(t)) = 0 identically',\n                        'formulaLatex': 'F(\\\\mathbf{r}(t)) = 0 \\\\quad\\\\text{and}\\\\quad G(\\\\mathbf{r}(t)) = 0 \\\\quad \\\\forall t \\\\in D',\n                        'explanation': 'Both original surface equations are verified algebraically to simplify identically to zero.',\n                    },\n                    {\n                        'stepNumber': 5,\n                        'title': 'Verify global coverage',\n                        'formulaText': cov_reason,\n                        'formulaLatex': f\"\\\\text{{{cov_reason}}}\",\n                        'explanation': 'Verified complete global coverage without branch omission or sign-constrained loss.',\n                    },\n                    {\n                        'stepNumber': 6,\n                        'title': 'Result scope and component coverage',\n                        'formulaText': scope,\n                        'formulaLatex': f\"\\\\text{{{scope}}}\",\n                        'explanation': f'Established result coverage: {scope}.',\n                    }\n                ]\n            }\n\n            canonical_curve = {\n                'paramSymbol': 't',\n                'x': str(rx),\n                'y': str(ry),\n                'z': str(rz),\n                'latex': {\n                    'x': sp.latex(rx),\n                    'y': sp.latex(ry),\n                    'z': sp.latex(rz),\n                },\n                'domain': {\n                    'intervals': intervals,\n                    'description': domain_desc or 'Valid parameter intervals'\n                },\n                'direction': 'forward',\n                'verification': {\n                    'status': 'verified',\n                    'scope': f'Algebraically verified {scope}.',\n                    'surfaceFIdentityHolds': True,\n                    'surfaceGIdentityHolds': True,\n                    'domainSingularitiesChecked': True,\n                    'method': 'symbolic_identity',\n                    'verifiedAt': 1700000000000\n                }\n            }\n\n            candidates.append({\n                'score': score,\n                'canonicalCurve': canonical_curve,\n                'derivation': derivation,\n                'scope': scope,\n            })\n\n    if not candidates:\n        return None, has_incomplete_branches\n\n    candidates.sort(key=lambda c: (-c['score'], str(c['canonicalCurve']['x'])))\n    best = candidates[0]\n    best_scope = best['scope']\n    if len(candidates) > 1:\n        best_scope = f\"Verified component (1 of {len(candidates)} candidates); additional components may exist\"\n\n    wrapped = wrap_solved_curve(\n        best['canonicalCurve'],\n        best['derivation'],\n        F_res,\n        G_res,\n        bounds,\n        direction,\n        best_scope,\n        len(candidates)\n    )\n    return wrapped, False\n\n\ndef solve_intersection_core(F_res, G_res, domain_conds=None, bounds=DEFAULT_BOUNDS, direction='forward', f_eq_str=None, g_eq_str=None):\n    bounds = normalize_bounds(bounds)\n    # Strategy 0: Trivial contradiction / emptiness / degeneracy\n    res0 = check_trivial_emptiness_or_degeneracy(F_res, G_res, bounds)\n    if res0:\n        return res0\n\n    # Strategy 1: Linear affine system\n    res1 = solve_linear(F_res, G_res, bounds, domain_conds, direction, f_eq_str, g_eq_str)\n    if res1:\n        return res1\n\n    # Strategy 2: Plane + Sphere\n    res2 = solve_plane_sphere_system(F_res, G_res, bounds, direction, f_eq_str, g_eq_str)\n    if res2:\n        return res2\n\n    # Strategy 3: Cylinder + Surface (Plane or general surface)\n    res3 = solve_cylinder_surface_system(F_res, G_res, bounds, domain_conds, direction, f_eq_str, g_eq_str)\n    if res3:\n        return res3\n\n    # Strategy 4: Quadric-Quadric Reduction (e.g. Sphere + Sphere)\n    res4 = reduce_quadrics(F_res, G_res, bounds, direction, f_eq_str, g_eq_str)\n    if res4:\n        return res4\n\n    # Strategy 5: Coordinate Parameterization\n    res5, has_incomplete = solve_coordinate_parameterization(F_res, G_res, domain_conds, bounds, direction, f_eq_str, g_eq_str)\n    if res5:\n        return res5\n\n    # If branches exist but no single exact global parameterization covers all components (Rule 8)\n    if has_incomplete:\n        return {\n            'status': 'inconclusive',\n            'bounds': bounds,\n            'reasonCode': 'multiple_branches_no_global_parametrization',\n            'message': 'The complete intersection consists of multiple branches or disconnected components, and no single exact global parameterization could be determined.',\n            'searchDetails': 'Rejected candidate parameterizations that only covered a single branch or subset of the complete intersection.'\n        }\n\n    # Inconclusive fallback\n    return {\n        'status': 'inconclusive',\n        'bounds': bounds,\n        'reasonCode': 'search_exhausted',\n        'message': 'Could not determine an exact parameterization within the supported symbolic strategies.',\n        'searchDetails': 'Strategies attempted: Linear, PlaneSphere, CylinderSurface, QuadricReduction, CoordinateParameter.'\n    }\n\n\ndef solve_intersection_json(json_str):\n    \"\"\"\n    Main entry point for exact intersection solving (Phase V4 & V5).\n    Accepts JSON with surface plans, bounds, and direction ('forward' | 'reverse').\n    Returns JSON serialized CalculationResult.\n    \"\"\"\n    data = json.loads(json_str)\n\n    def extract_plan(obj):\n        if not obj or not isinstance(obj, dict):\n            return obj\n        if 'equation' in obj and 'planVersion' in obj:\n            return obj\n        if 'sympyPlan' in obj:\n            return obj['sympyPlan']\n        if 'prepared' in obj and isinstance(obj['prepared'], dict):\n            prep = obj['prepared']\n            if 'sympyPlan' in prep:\n                return prep['sympyPlan']\n        return obj\n\n    plan_f = extract_plan(data.get('surfaceF'))\n    plan_g = extract_plan(data.get('surfaceG'))\n    bounds = normalize_bounds(data.get('bounds', DEFAULT_BOUNDS))\n    direction = data.get('direction', 'forward')\n    if direction not in ('forward', 'reverse'):\n        direction = 'forward'\n\n    if not plan_f or not plan_g:\n        raise ValueError(\"Payload must contain both 'surfaceF' and 'surfaceG' plans\")\n\n    eq_f = plan_f.get('equation')\n    if not eq_f or eq_f.get('op') != 'Eq':\n        raise ValueError(\"surfaceF missing valid Eq relation\")\n    lhs_f = build_step(eq_f['args'][0])\n    rhs_f = build_step(eq_f['args'][1])\n    f_res = lhs_f - rhs_f\n    f_eq_str = plan_f.get('rawInput') or f\"{lhs_f} = {rhs_f}\"\n\n    eq_g = plan_g.get('equation')\n    if not eq_g or eq_g.get('op') != 'Eq':\n        raise ValueError(\"surfaceG missing valid Eq relation\")\n    lhs_g = build_step(eq_g['args'][0])\n    rhs_g = build_step(eq_g['args'][1])\n    g_res = lhs_g - rhs_g\n    g_eq_str = plan_g.get('rawInput') or f\"{lhs_g} = {rhs_g}\"\n\n    domain_conds = []\n    for plan in (plan_f, plan_g):\n        for cond in plan.get('domainConditions', []):\n            c_step = cond.get('condition')\n            if c_step:\n                domain_conds.append({\n                    'id': cond.get('id', ''),\n                    'kind': cond.get('kind', ''),\n                    'expr': build_step(c_step),\n                    'description': cond.get('description', '')\n                })\n\n    result = solve_intersection_core(f_res, g_res, domain_conds, bounds, direction, f_eq_str, g_eq_str)\n    return json.dumps(result)\n";
